n=17; center=n//2; grid=[]
for r in range(n):
 row=[0]*n
 if r<=center:
  for c in {center-r,center+r}: row[c]=2
 if r>=3:
  for c in range(n):
   if c%4==(r+center)%4 and row[c]==0: row[c]=1
 grid.append(row)
print(grid)

n=17; m=n//2; g=[]
for r in range(n):
 row=[0]*n
 if r<=m:
  lo,hi=m-r,m+r
  row[lo]=2; row[hi]=2
 if r>=3:
  for c in range(n):
   if c%4==(r+m)%4 and (r>m or (m-r<=c<=m+r)):
    if row[c]==0: row[c]=1
